let feedOk = false;

function postOut(r) {
  const j = (v, d) => { try { const o = JSON.parse(v || ""); return o == null ? d : o; } catch (e) { return d; } };
  return {
    id: r.id, uid: r.uid, name: r.name, body: r.body,
    body_en: r.body_en || "", body_zh: r.body_zh || "",
    photos: j(r.photos, []), kind: r.kind || "company",
    likes: j(r.likes, []), comments: j(r.comments, []),
    created_at: r.created_at,
  };
}

/* 老动态那 10 张图先在包里，首次请求时搬进 R2；搬完就只走 R2 */
async function seedOldMedia(env) {
  if (!env.PHOTOS) return;
  const names = Object.keys(OLD_IMG);
  if (!names.length) return;
  try {
    if (await env.PHOTOS.head("feed/old/" + names[0])) return;
    for (const n of names) {
      const bytes = Uint8Array.from(atob(OLD_IMG[n]), (c) => c.charCodeAt(0));
      await env.PHOTOS.put("feed/old/" + n, bytes, { httpMetadata: { contentType: "image/jpeg" } });
    }
  } catch (e) {}
}

async function feedSchema(env) {
  if (feedOk) return;
  await env.DB.prepare(
    `CREATE TABLE IF NOT EXISTS posts (
       id TEXT PRIMARY KEY, uid TEXT NOT NULL, name TEXT NOT NULL DEFAULT '',
       body TEXT NOT NULL DEFAULT '', photos TEXT NOT NULL DEFAULT '[]',
       kind TEXT NOT NULL DEFAULT 'company', likes TEXT NOT NULL DEFAULT '[]',
       comments TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL)`
  ).run();
  for (const sql of [
    "ALTER TABLE posts ADD COLUMN kind TEXT NOT NULL DEFAULT 'company'",
    "ALTER TABLE posts ADD COLUMN likes TEXT NOT NULL DEFAULT '[]'",
    "ALTER TABLE posts ADD COLUMN comments TEXT NOT NULL DEFAULT '[]'",
    "ALTER TABLE posts ADD COLUMN body_en TEXT NOT NULL DEFAULT ''",
    "ALTER TABLE posts ADD COLUMN body_zh TEXT NOT NULL DEFAULT ''",
  ]) { try { await env.DB.prepare(sql).run(); } catch (e) {} }
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS posts_time ON posts(created_at)`).run();
  await env.DB.prepare("DELETE FROM posts WHERE id LIKE 'legacy-%'").run();
  await seedOldMedia(env);
  const have = await env.DB.prepare("SELECT COUNT(*) n FROM posts WHERE id LIKE 'old-%'").first();
  if (!have || !have.n) {
    for (const p of OLD_POSTS) {
      await env.DB.prepare("INSERT OR IGNORE INTO posts(id,uid,name,body,photos,kind,created_at) VALUES(?,?,?,?,?,?,?)")
        .bind(p.id, "old", p.by, p.text, JSON.stringify(p.media || []), p.kind || "company", p.at).run();
    }
  } else {
    for (const p of OLD_POSTS) {
      await env.DB.prepare("UPDATE posts SET photos=?, kind=? WHERE id=? AND uid='old'")
        .bind(JSON.stringify(p.media || []), p.kind || "company", p.id).run();
    }
  }
  feedOk = true;
}

async function feedApi(req, env, me, seg, body) {
  await feedSchema(env);
  const id = seg[1] || "";
  const sub = seg[2] || "";
  const meId = me.login || me.uid;

  /* 老图兜底（R2 还没搬完时也能看） */
  if (id === "img" && req.method === "GET") {
    const b64 = OLD_IMG[seg.slice(2).join("/")];
    if (!b64) return err("没有这张图", 404);
    const bytes = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
    return new Response(bytes, { headers: { "content-type": "image/jpeg", "cache-control": "private, max-age=31536000" } });
  }

  if (!id && req.method === "GET") {
    const rows = await env.DB.prepare("SELECT * FROM posts ORDER BY created_at DESC LIMIT 100").all();
    return json({ posts: rows.results.map(postOut) });
  }

  if (!id && req.method === "POST") {
    const b = await body();
    const text = String(b.body || "").trim().slice(0, 2000);
    const photos = normMedia(b.photos);
    if (!text && !photos.length) return err("写点内容再发");
    const pid = crypto.randomUUID().replace(/-/g, "").slice(0, 20);
    const tr = await trPair(env, text);
    await env.DB.prepare("INSERT INTO posts(id,uid,name,body,body_en,body_zh,photos,kind,likes,comments,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)")
      .bind(pid, meId, me.name || meId, text, tr.en, tr.zh, JSON.stringify(photos), "company", "[]", "[]", nowISO()).run();
    return json({ ok: true, id: pid }, 201);
  }

  const row = id ? await env.DB.prepare("SELECT * FROM posts WHERE id=?").bind(id).first() : null;
  if (id && !row) return err("这条动态不存在", 404);
  const own = !!row && (row.uid === meId || me.role === "admin");

  if (id && sub === "like" && req.method === "POST") {
    const p = postOut(row);
    const likes = p.likes.includes(meId) ? p.likes.filter((x) => x !== meId) : p.likes.concat([meId]);
    await env.DB.prepare("UPDATE posts SET likes=? WHERE id=?").bind(JSON.stringify(likes), id).run();
    return json({ ok: true, likes });
  }

  if (id && sub === "comment" && !seg[3] && req.method === "POST") {
    const b = await body();
    const text = String(b.text || "").trim().slice(0, 300);
    if (!text) return err("写点留言");
    const p = postOut(row);
    const tr = await trPair(env, text);
    p.comments.push({ uid: meId, by: me.name || meId, text, text_en: tr.en, text_zh: tr.zh, at: nowISO() });
    await env.DB.prepare("UPDATE posts SET comments=? WHERE id=?").bind(JSON.stringify(p.comments), id).run();
    return json({ ok: true, comments: p.comments });
  }

  if (id && sub === "comment" && seg[3] !== undefined && req.method === "DELETE") {
    const p = postOut(row);
    const i = +seg[3];
    if (!p.comments[i]) return err("没有这条留言", 404);
    if (p.comments[i].uid !== meId && me.role !== "admin") return err("只能删自己的留言", 403);
    p.comments.splice(i, 1);
    await env.DB.prepare("UPDATE posts SET comments=? WHERE id=?").bind(JSON.stringify(p.comments), id).run();
    return json({ ok: true });
  }

  if (id && !sub && req.method === "PATCH") {
    if (!own) return err("只能改自己发的", 403);
    const b = await body();
    const text = String(b.body || "").trim().slice(0, 2000);
    const photos = b.photos === undefined ? postOut(row).photos : normMedia(b.photos);
    const tr = await trPair(env, text);
    await env.DB.prepare("UPDATE posts SET body=?, body_en=?, body_zh=?, photos=? WHERE id=?")
      .bind(text, tr.en, tr.zh, JSON.stringify(photos), id).run();
    return json({ ok: true });
  }

  if (id && !sub && req.method === "DELETE") {
    if (!own) return err("只能删自己发的", 403);
    await env.DB.prepare("DELETE FROM posts WHERE id=?").bind(id).run();
    return json({ ok: true });
  }

  return err("不支持的操作", 404);
}

function normMedia(list) {
  if (!Array.isArray(list)) return [];
  return list.slice(0, 9).map((m) => (typeof m === "string"
    ? { t: "i", u: m }
    : { t: m && m.t === "v" ? "v" : "i", u: String((m && m.u) || "") }))
    .filter((m) => m.u);
}

